		StringBuilder msg = new StringBuilder( "-- Failed to get all PaymentMethod : " );        
		List<PaymentMethod> collection  = new ArrayList<>();

		try {
			// call the static get method on the PaymentMethodService
			collection = PaymentMethodService.getPaymentMethodInstance().getAllPaymentMethod();
			assertNotNull( collection, "An Empty collection of PaymentMethod was incorrectly returned.");
			
			// Now print out the values
			PaymentMethod entity = null;            
			Iterator<PaymentMethod> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPaymentMethodId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
